(()=>{
'use strict';
const K=window.KingdomSim,N=window.NavalUI,$=id=>document.getElementById(id);let api,dirty=false;
const setup=document.createElement('section');setup.className='coalition-setup';setup.innerHTML='<label>电脑数量 <select id="ai-count"><option value="1">1 名电脑</option><option value="2">2 名电脑</option><option value="3" selected>3 名电脑</option></select></label><p>你固定在第 1 队。同队共享胜负；不同队默认敌对。可重复选择国家。</p><div id="ai-rows"></div>';
document.querySelector('.opponent-choice').hidden=true;document.querySelector('.nation-picker').append(setup);
for(let t=1;t<=3;t++){const row=document.createElement('div');row.className='ai-row';row.dataset.player=t;row.innerHTML='<b style="color:'+K.colors[t]+'">电脑 '+t+'</b><select aria-label="电脑 '+t+' 国家" id="ai-nation-'+t+'">'+Object.values(K.nations).map(n=>'<option value="'+n.id+'">'+n.name+'</option>').join('')+'</select><select aria-label="电脑 '+t+' 队伍" id="ai-group-'+t+'">'+[1,2,3,4].map(g=>'<option value="'+g+'">第 '+g+' 队'+(g===1?' · 盟友':'')+'</option>').join('')+'</select>';$('ai-rows').append(row);$('ai-nation-'+t).value=['france','china','britain'][t-1];$('ai-group-'+t).value=t===2?'1':'2'}
function rows(){for(const row of $('ai-rows').children)row.hidden=Number(row.dataset.player)>Number($('ai-count').value)}
setup.onchange=()=>{dirty=true;rows();$('start').innerHTML='按国家与队伍设置开始 <span>→</span>'};rows();
const nativeNations=N.nations.bind(N),nativeRestore=N.restore.bind(N),nativeBind=N.bind.bind(N),nativeClear=N.clearChanged.bind(N);
N.options=()=>({nations:[nativeNations()[0],...[1,2,3].slice(0,Number($('ai-count').value)).map(t=>$('ai-nation-'+t).value)],groups:[1,...[1,2,3].slice(0,Number($('ai-count').value)).map(t=>Number($('ai-group-'+t).value))]});
N.valid=()=>{const valid=N.options().groups.some(g=>g!==1);let message=$('team-error');if(!message){message=document.createElement('p');message.id='team-error';message.style.color='#efb099';setup.append(message)}message.textContent=valid?'':'至少需要一名不同队伍的电脑对手。';return valid};
N.nations=()=>N.options().nations;N.clearChanged=()=>{nativeClear();dirty=false};
const oldChanged=Object.getOwnPropertyDescriptor(N,'changed').get;Object.defineProperty(N,'changed',{get:()=>dirty||oldChanged.call(N)});
N.restore=s=>{nativeRestore(s);$('ai-count').value=s.nations.length-1;for(let t=1;t<s.nations.length;t++){$('ai-nation-'+t).value=s.nations[t];$('ai-group-'+t).value=s.groups?.[t]??t}rows();dirty=false};
N.bind=value=>{api=value;nativeBind(value)};
const zoom=document.createElement('div');zoom.id='zoom-panel';zoom.innerHTML='<button id="fit-map" title="查看全地图">全图</button><input id="zoom-range" type="range" min="6" max="350" value="100" aria-label="地图缩放百分比"><span id="zoom-level">100%</span>';document.querySelector('.battlefield').append(zoom);$('zoom-range').oninput=()=>api.zoom(Number($('zoom-range').value)/100);$('fit-map').onclick=()=>api.fitMap();
const diplomacy=document.createElement('button');diplomacy.id='diplomacy';diplomacy.textContent='⚑';diplomacy.setAttribute('aria-label','外交与贸易');diplomacy.title='外交、队伍与商队贸易';$('help').before(diplomacy);
const dialog=document.createElement('dialog');dialog.id='diplomacy-dialog';dialog.innerHTML='<div class="diplomacy-head"><div><small>KINGDOM COUNCIL</small><h2>外交与贸易</h2></div><button id="close-diplomacy" aria-label="关闭外交面板">×</button></div><p>同队不会互相攻击，共享胜负。敌国可花费 120 黄金签订停战贸易，60 秒后可解除；停战不改变最终胜利目标。</p><div id="diplomacy-players"></div><section><h3>商队路线</h3><p>建造市场并训练商队。选择商队后设置路线；未选商队时安排本国全部商队。新商队会自动寻找路线，走完往返后结算黄金，外国市场获得 50% 分成。</p><select id="trade-destination" aria-label="贸易目的地"></select><button id="assign-trade">安排商队往返</button><p id="trade-income"></p></section><p id="diplomacy-feedback" role="status"></p>';
document.body.append(dialog);let wasPaused=false;
function render(){const sim=api.getSim(),s=sim.state;$('diplomacy-players').replaceChildren();for(let t=0;t<s.nations.length;t++){const row=document.createElement('div');row.className='diplomacy-row';const defeated=s.defeated.includes(t),ally=sim.allied(0,t),pact=s.pacts[sim.pair(0,t)];row.innerHTML='<div><b style="color:'+K.colors[t]+'">'+sim.label(t)+'</b><small>第 '+s.groups[t]+' 队 · '+(defeated?'已退出':t===0?'本国':ally?'同队盟友':pact?'停战贸易':'敌对')+'</small></div>';if(t&&!defeated&&!ally){const b=document.createElement('button');b.textContent=pact?'终止协定':'停战贸易 · 120 金';b.onclick=()=>{$('diplomacy-feedback').textContent=sim.pact(t);api.refresh();render()};row.append(b)}$('diplomacy-players').append(row)}const previous=$('trade-destination').value,targets=sim.tradeTargets(0);$('trade-destination').replaceChildren();for(const target of targets){const o=document.createElement('option');o.value=target.id;o.textContent=target.type==='post'?'中立 · '+target.name:sim.label(target.team)+' · 市场 #'+target.id;$('trade-destination').append(o)}if(targets.some(p=>String(p.id)===previous))$('trade-destination').value=previous;$('trade-income').textContent='本国商队 '+s.units.filter(u=>u.team===0&&u.kind==='trader').length+' 支 · 累计贸易黄金 '+Math.floor(s.tradeGold[0]||0)}
diplomacy.onclick=()=>{wasPaused=api.isPaused();api.pause(true);render();dialog.showModal()};$('close-diplomacy').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{if(!wasPaused)api.pause(false)});
$('assign-trade').onclick=()=>{const sim=api.getSim(),selected=api.getSelection(),all=sim.state.units.filter(u=>u.team===0&&u.kind==='trader'),chosen=all.filter(u=>selected.includes(u.id)),units=chosen.length?chosen:all;let count=0,error='请先在市场训练商队';const id=$('trade-destination').value,target=sim.tradeTargets(0).find(p=>String(p.id)===id);for(const u of units){error=sim.route(u,target?.id);if(!error)count++}$('diplomacy-feedback').textContent=count?'已安排 '+count+' 支商队，完成往返后结算。':error;api.refresh();render()};
const audioButton=document.createElement('button');audioButton.id='audio-settings';audioButton.className='secondary';audioButton.textContent='声音与音乐';$('change-nation').after(audioButton);
const audioDialog=document.createElement('dialog');audioDialog.id='audio-dialog';audioDialog.innerHTML='<div class="diplomacy-head"><div><small>SOUNDS OF THE KINGDOM</small><h2>声音与音乐</h2></div><button id="close-audio" aria-label="关闭声音设置">×</button></div><p>原创中世纪风格编曲：拨弦、木笛、低音与鼓点。金属碰撞、木锤施工、枪炮和落成钟声独立混音。</p><label><input id="music-enabled" type="checkbox" checked> 播放背景音乐</label><label>音乐音量 <input id="music-volume" type="range" min="0" max="70" value="27" aria-label="音乐音量"></label><label>音效音量 <input id="fx-volume" type="range" min="0" max="100" value="55" aria-label="音效音量"></label><div class="sound-previews"><button data-sound="melee">试听兵器碰撞</button><button data-sound="hammer">试听施工敲击</button><button data-sound="complete-town">试听建筑落成</button><button data-sound="cannon">试听炮击</button></div><p>顶部 ♪ 按钮控制音效；背景音乐可在这里单独关闭。</p>';document.body.append(audioDialog);audioButton.onclick=()=>{const state=window.KingdomArt.audioStatus();$('music-enabled').checked=state.musicEnabled;$('music-volume').value=state.music*100;$('fx-volume').value=state.fx*100;audioDialog.showModal();window.KingdomArt.audioStart()};$('close-audio').onclick=()=>audioDialog.close();for(const id of ['music-enabled','music-volume','fx-volume'])$(id).oninput=()=>window.KingdomArt.setAudio({musicEnabled:$('music-enabled').checked,music:Number($('music-volume').value)/100,fx:Number($('fx-volume').value)/100});for(const b of audioDialog.querySelectorAll('[data-sound]'))b.onclick=()=>{window.KingdomArt.audioStart();window.KingdomArt.sound(b.dataset.sound)};
// Game gestures are handled by the canvas. Double taps must never zoom the page.
document.addEventListener('dblclick',e=>{if(e.target.closest('#game,dialog'))e.preventDefault()},{passive:false});
let lastTouch=0;document.addEventListener('touchend',e=>{if(!e.target.closest('#game'))return;const now=Date.now();if(e.touches.length===0&&now-lastTouch<320)e.preventDefault();lastTouch=now},{passive:false});
for(const event of ['gesturestart','gesturechange','gestureend'])document.addEventListener(event,e=>{if(e.target.closest('#game'))e.preventDefault()},{passive:false});
})();
